    public PolicyService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PolicyEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PolicyRepository.class) );
		this.validator		= applicationContext.getBean(PolicyValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Policy
	 */
		public Policy createPolicy( CreatePolicyCommand command ) {

		Policy entity = new Policy();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPolicyId( command.getPolicyId() );
            entity.setTitle( command.getTitle() );
            entity.setVersionLabel( command.getVersionLabel() );
            entity.setApprovalDate( command.getApprovalDate() );
            entity.setNextReviewDate( command.getNextReviewDate() );
            entity.setDocumentUrl( command.getDocumentUrl() );
            entity.setPolicyType( command.getPolicyType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Policy {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePolicyCommand
	 * @return		Policy
	 */
	public Policy updatePolicy( UpdatePolicyCommand command ) {

		Policy entity = new Policy();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPolicyId( command.getPolicyId() );
            entity.setTitle( command.getTitle() );
            entity.setVersionLabel( command.getVersionLabel() );
            entity.setApprovalDate( command.getApprovalDate() );
            entity.setNextReviewDate( command.getNextReviewDate() );
            entity.setDocumentUrl( command.getDocumentUrl() );
            entity.setOrganization( command.getOrganization() );
            entity.setOwners( command.getOwners() );
            entity.setRelatedRequirements( command.getRelatedRequirements() );
            entity.setControls( command.getControls() );
            entity.setProcedures( command.getProcedures() );
            entity.setExceptions( command.getExceptions() );
            entity.setAttestations( command.getAttestations() );
            entity.setPolicyType( command.getPolicyType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Policy {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePolicyCommand
	 */
	public void delete( DeletePolicyCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPolicyId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Policy {0} ", id );

	}

	/**
	 * Method to retrieve the Policy via PolicyFetchOneSummary
	 * @param 	summary PolicyFetchOneSummary
	 * @return 	PolicyFetchOneResponse
	 */
	public Policy getPolicy( PolicyFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PolicyFetchOneSummary arg cannot be null" );

		Policy entity = null;
		UUID id = summary.getPolicyId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Policy using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Policys
	 *
	 * @return 	List<Policy>
	 */
    public List<Policy> getAllPolicy() {
		List<Policy> list = projector.findAll( new FindAllPolicyQuery() );
		return list;
	}

	/**
	 * assign Organization on Policy
	 * @param		command AssignOrganizationToPolicyCommand
	 */
	public void assignOrganization( AssignOrganizationToPolicyCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getPolicyId(), command.getAssignment());

	}

